import json
from pathlib import Path
from typing import Dict, List, Optional

from pydantic import BaseModel, ConfigDict, Field

from intelligent_security.domain import PluginAdapter


class PluginRuntimeProfile(BaseModel):
    """Operator-owned runtime configuration; never generated by the planner."""

    model_config = ConfigDict(extra="forbid")

    plugin_id: str = Field(..., min_length=3, max_length=200)
    adapter: PluginAdapter
    runtime_reference: str = Field(..., min_length=8, max_length=1024, pattern=r"^[A-Za-z][A-Za-z0-9+.-]*://\S+$")
    image_reference: Optional[str] = Field(default=None, min_length=1, max_length=1024)
    max_runtime_seconds: int = Field(default=300, ge=30, le=3600)
    allowed_target_hosts: List[str] = Field(default_factory=list, max_length=100)
    enabled: bool = True


class PluginRuntimeProfileRegistry:
    def __init__(self, path: Optional[str] = None) -> None:
        default_path = Path("config/plugin_runtimes.json")
        self.path = Path(path) if path else default_path

    def load(self) -> Dict[str, PluginRuntimeProfile]:
        if not self.path.exists():
            return {}
        try:
            content = json.loads(self.path.read_text(encoding="utf-8"))
            profiles = [PluginRuntimeProfile.model_validate(item) for item in content.get("plugins", [])]
        except (OSError, ValueError, TypeError) as error:
            raise RuntimeProfileError("Unable to load plugin runtime profiles: {}".format(error))
        plugin_ids = [profile.plugin_id for profile in profiles]
        if len(plugin_ids) != len(set(plugin_ids)):
            raise RuntimeProfileError("Plugin runtime profiles contain duplicate plugin_id values.")
        return {profile.plugin_id: profile for profile in profiles}


class RuntimeProfileError(Exception):
    pass
